import{_ as h,C as c,o,c as p,a9 as a,b as n,w as t,a as s,E as r,a8 as d}from"./chunks/framework.BOiBTRPC.js";const v=JSON.parse('{"title":"Lambda & Kappa Architectures","description":"The dual-path Lambda architecture, the log-centric Kappa alternative, and the unified-engine / medallion pattern that actually won.","frontmatter":{"title":"Lambda & Kappa Architectures","description":"The dual-path Lambda architecture, the log-centric Kappa alternative, and the unified-engine / medallion pattern that actually won."},"headers":[],"relativePath":"pipelines/lambda-kappa.md","filePath":"pipelines/lambda-kappa.md"}'),u={name:"pipelines/lambda-kappa.md"};function m(g,e,b,y,f,w){const i=c("Mermaid"),l=c("QuizCard");return o(),p("div",null,[e[6]||(e[6]=a('<h1 id="lambda-kappa-architectures" tabindex="-1">Lambda &amp; Kappa Architectures <a class="header-anchor" href="#lambda-kappa-architectures" aria-label="Permalink to &quot;Lambda &amp; Kappa Architectures&quot;">​</a></h1><blockquote><p><strong>Why it matters</strong> — &quot;We need low-latency dashboards <em>and</em> correct historical numbers&quot; is the oldest hard problem in data engineering. Lambda solved it by running two pipelines; Kappa solved it by making the log the source of truth. Understanding both — and why modern engines made Lambda mostly unnecessary — is core senior-engineer fluency and the right answer to half the architecture questions in interviews.</p></blockquote><h2 id="the-problem-both-solve" tabindex="-1">The problem both solve <a class="header-anchor" href="#the-problem-both-solve" aria-label="Permalink to &quot;The problem both solve&quot;">​</a></h2><p>You want:</p><ol><li><strong>Fresh data</strong> — dashboards, alerts, personalization that update in seconds</li><li><strong>Correct history</strong> — the ability to recompute the &quot;true&quot; answer when bugs, late data, or business-rule changes invalidate what you previously served</li></ol><p>A single batch job gives you #2 but not #1. A pure streaming job gives you #1 but historically struggled with #2 — reprocessing months of state, upgrading code without losing checkpointed state, and keeping long-term aggregates consistent.</p><h2 id="lambda-architecture" tabindex="-1">Lambda architecture <a class="header-anchor" href="#lambda-architecture" aria-label="Permalink to &quot;Lambda architecture&quot;">​</a></h2><p>Nathan Marz&#39;s <em>Big Data</em> (2013) formalized the pattern:</p>',8)),(o(),n(d,null,{default:t(()=>[r(i,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20subgraph%20Input%5B%22Incoming%20data%22%5D%0A%20%20%20%20%20%20%20%20D%5B%22All%20events%20%2F%20records%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Lambda%5B%22Lambda%20architecture%22%5D%0A%20%20%20%20%20%20%20%20direction%20TB%0A%20%20%20%20%20%20%20%20BL%5B%22Batch%20layer%3Cbr%2F%3Ereprocesses%20all%20data%3Cbr%2F%3Eproduces%20the%20master%20dataset%22%5D%0A%20%20%20%20%20%20%20%20SL%5B%22Speed%20layer%3Cbr%2F%3Eprocesses%20recent%20data%20only%3Cbr%2F%3Ecompensates%20for%20batch%20latency%22%5D%0A%20%20%20%20%20%20%20%20SV%5B%22Serving%20layer%3Cbr%2F%3Emerges%20batch%20%2B%20speed%20views%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Out%5B%22Consumers%22%5D%0A%20%20%20%20%20%20%20%20Q%5B%22Queries%20get%20merged%20results%22%5D%0A%20%20%20%20end%0A%20%20%20%20D%20--%3E%20BL%0A%20%20%20%20D%20--%3E%20SL%0A%20%20%20%20BL%20--%3E%20SV%0A%20%20%20%20SL%20--%3E%20SV%0A%20%20%20%20SV%20--%3E%20Q%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=a('<ul><li><strong>Batch layer</strong> — stores the immutable master dataset (HDFS/S3), periodically recomputes views over <em>all</em> data. Expensive but simple and correct.</li><li><strong>Speed layer</strong> — processes only recent events to cover the window the batch layer hasn&#39;t reached yet. Often a streaming engine with approximate/incremental logic.</li><li><strong>Serving layer</strong> — indexes both outputs and merges them at query time, e.g., &quot;real-time count = batch count + speed count for recent window.&quot;</li></ul><div class="warning custom-block"><p class="custom-block-title">⚠️ Risk / production failure mode</p><p>The canonical Lambda failure is <strong>dual-codebase drift</strong>: the batch logic in Spark/Hive and the speed logic in Storm/Flink implement the same business rule, differently. A &quot;users who purchased&quot; definition diverges by a boundary condition and the merged view returns inconsistent counts. Keeping two pipelines in semantic lockstep is the permanent tax.</p></div><table tabindex="0"><thead><tr><th>Layer</th><th>Tooling era</th><th>Typical weakness</th></tr></thead><tbody><tr><td>Batch</td><td>Hadoop MapReduce → Hive → Spark</td><td>hours of lag between recomputes</td></tr><tr><td>Speed</td><td>Storm → Spark Streaming → Flink</td><td>only holds recent state; approximates complex joins</td></tr><tr><td>Serving</td><td>Druid, Pinot, custom KV stores</td><td>merge logic is often bespoke and fragile</td></tr></tbody></table><h2 id="kappa-architecture" tabindex="-1">Kappa architecture <a class="header-anchor" href="#kappa-architecture" aria-label="Permalink to &quot;Kappa architecture&quot;">​</a></h2><p>Jay Kreps&#39; 2014 counterargument: you don&#39;t need a batch layer if your <strong>log is the source of truth</strong>. Run everything through a stream processor; when you need to &quot;reprocess history,&quot; replay the log.</p>',5)),(o(),n(d,null,{default:t(()=>[r(i,{id:"mermaid-114",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20subgraph%20K%5B%22Kappa%20architecture%22%5D%0A%20%20%20%20%20%20%20%20direction%20TB%0A%20%20%20%20%20%20%20%20L%5B%22Append-only%20log%3Cbr%2F%3Ethe%20source%20of%20truth%22%5D%0A%20%20%20%20%20%20%20%20SP%5B%22Stream%20processor%3Cbr%2F%3Eone%20codebase%20for%20everything%22%5D%0A%20%20%20%20%20%20%20%20V%5B%22Materialized%20views%20%2F%20tables%22%5D%0A%20%20%20%20%20%20%20%20R%5B%22Replay%20for%20reprocessing%22%5D%0A%20%20%20%20end%0A%20%20%20%20L%20--%3E%20SP%0A%20%20%20%20L%20--%3E%20R%0A%20%20%20%20R%20--%3E%20SP%0A%20%20%20%20SP%20--%3E%20V%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[s(" Loading... ",-1)])]),_:1})),e[8]||(e[8]=a('<ul><li><strong>One codebase</strong> — no speed/batch drift because there is only one path</li><li><strong>The log is the database</strong> — immutable, replayable, ordered</li><li><strong>Reprocessing = replay</strong> — fix a bug, redeploy, rewind offsets, and let the stream processor recompute from scratch</li></ul><div class="tip custom-block"><p class="custom-block-title">💡 Senior insight</p><p>Kappa&#39;s insight is architectural inversion: instead of <em>deriving the log from tables</em>, you <em>derive tables from the log</em>. This is the same mental model as CDC (covered in the next chapter) and event sourcing. Once the log is primary, &quot;batch&quot; becomes just a replay with a big window.</p></div><table tabindex="0"><thead><tr><th>Property</th><th>Lambda</th><th>Kappa</th></tr></thead><tbody><tr><td>Codebases</td><td>two (batch + speed)</td><td>one</td></tr><tr><td>Source of truth</td><td>batch layer (master dataset)</td><td>the log itself</td></tr><tr><td>Reprocessing</td><td>rerun batch job</td><td>replay log from offset 0 or a timestamp</td></tr><tr><td>Latency</td><td>low (speed layer)</td><td>low</td></tr><tr><td>Operational cost</td><td>two systems to run</td><td>one system + log retention</td></tr><tr><td>Correctness risk</td><td>speed/batch divergence</td><td>replay determinism, state compatibility</td></tr></tbody></table><h2 id="kappa-unified-engines" tabindex="-1">Kappa+ / unified engines <a class="header-anchor" href="#kappa-unified-engines" aria-label="Permalink to &quot;Kappa+ / unified engines&quot;">​</a></h2><p>The 2020s brought the middle path: <strong>one engine that can run in both modes</strong>. Spark Structured Streaming and Apache Flink both treat batch as a special case of streaming (a bounded stream), so a single job can process history and then seamlessly tail the live stream.</p>',5)),(o(),n(d,null,{default:t(()=>[r(i,{id:"mermaid-226",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20U%5B%22Unified%20engine%22%5D%0A%20%20%20%20%20%20%20%20direction%20TB%0A%20%20%20%20%20%20%20%20E1%5B%22Spark%20Structured%20Streaming%3Cbr%2F%3Emicro-batch%20%2B%20continuous%22%5D%0A%20%20%20%20%20%20%20%20E2%5B%22Apache%20Flink%3Cbr%2F%3Eevent-at-a-time%20%2B%20batch%20mode%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Data%5B%22Data%22%5D%0A%20%20%20%20%20%20%20%20D1%5B%22Bounded%20history%3Cbr%2F%3Efiles%2C%20partitions%2C%20table%20snapshots%22%5D%0A%20%20%20%20%20%20%20%20D2%5B%22Unbounded%20stream%3Cbr%2F%3EKafka%2C%20Pulsar%22%5D%0A%20%20%20%20end%0A%20%20%20%20D1%20--%3E%20E1%0A%20%20%20%20D1%20--%3E%20E2%0A%20%20%20%20D2%20--%3E%20E1%0A%20%20%20%20D2%20--%3E%20E2%0A"})]),fallback:t(()=>[...e[2]||(e[2]=[s(" Loading... ",-1)])]),_:1})),e[9]||(e[9]=a('<ul><li><strong>Spark Structured Streaming</strong> — micro-batch engine; run <code>Trigger.Once()</code> or <code>Trigger.AvailableNow()</code> for batch-style execution, <code>Trigger.ProcessingTime</code> for continuous</li><li><strong>Flink</strong> — originally streaming-first; <code>ExecutionMode.BATCH</code> gives true bounded-data batch execution with its own optimizations, used by Flink CDC and lakehouse ingest</li></ul><div class="info custom-block"><p class="custom-block-title">ℹ️ Note</p><p>Lambda is not dead — it survives where the serving layer has genuinely different access patterns (e.g., Pinot/Druid for sub-second OLAP + a warehouse for deep history). What died is the <em>two separate compute stacks</em> part; modern Lambda implementations unify compute and split only at the serving tier.</p></div><h2 id="medallion-architecture" tabindex="-1">Medallion architecture <a class="header-anchor" href="#medallion-architecture" aria-label="Permalink to &quot;Medallion architecture&quot;">​</a></h2><p>The pattern that quietly became the industry default is less an architecture than a <strong>layering discipline</strong>:</p>',4)),(o(),n(d,null,{default:t(()=>[r(i,{id:"mermaid-250",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20M%5B%22Medallion%22%5D%0A%20%20%20%20%20%20%20%20direction%20LR%0A%20%20%20%20%20%20%20%20B%5B%22Bronze%3Cbr%2F%3Eraw%2C%20append-only%3Cbr%2F%3Eschema-on-read%2C%20minimal%20validation%22%5D%0A%20%20%20%20%20%20%20%20S%5B%22Silver%3Cbr%2F%3Ecleaned%2C%20deduplicated%3Cbr%2F%3Etyped%2C%20joined%2C%20conformed%22%5D%0A%20%20%20%20%20%20%20%20G%5B%22Gold%3Cbr%2F%3Ebusiness-level%20aggregates%3Cbr%2F%3Emodeled%20for%20consumption%22%5D%0A%20%20%20%20end%0A%20%20%20%20B%20--%3E%20S%20--%3E%20G%0A%20%20%20%20subgraph%20Serve%5B%22Consumption%22%5D%0A%20%20%20%20%20%20%20%20C1%5B%22BI%20%2F%20dashboards%22%5D%0A%20%20%20%20%20%20%20%20C2%5B%22ML%20features%22%5D%0A%20%20%20%20%20%20%20%20C3%5B%22Data%20products%20%2F%20marts%22%5D%0A%20%20%20%20end%0A%20%20%20%20G%20--%3E%20Serve%0A"})]),fallback:t(()=>[...e[3]||(e[3]=[s(" Loading... ",-1)])]),_:1})),e[10]||(e[10]=a('<table tabindex="0"><thead><tr><th>Layer</th><th>Content</th><th>Guarantees</th><th>Typical operations</th></tr></thead><tbody><tr><td>Bronze</td><td>raw source data, minimal transform</td><td>append-only, audit trail</td><td>ingest, schema capture, dedupe keys</td></tr><tr><td>Silver</td><td>cleaned, typed, conformed</td><td>deduplicated, joins resolved, quality checks</td><td>dedupe, type enforcement, SCD handling, reference joins</td></tr><tr><td>Gold</td><td>business metrics &amp; dimensions</td><td>ready for consumption</td><td>aggregations, star schemas, data marts, feature tables</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">⚠️ Risk / production failure mode</p><p>Medallion&#39;s failure mode is <em>over-layering</em>: every hop becomes a full materialized table, so a simple metric requires three pipelines and triple storage. Discipline: only materialize a layer when you need a durable boundary (schema contract, quality gate, or different SLA); otherwise compute through.</p></div><h2 id="which-architecture-for-which-org-maturity" tabindex="-1">Which architecture for which org maturity <a class="header-anchor" href="#which-architecture-for-which-org-maturity" aria-label="Permalink to &quot;Which architecture for which org maturity&quot;">​</a></h2><p>There is no universal answer — the right choice depends on team size, latency requirements, and tolerance for operational complexity.</p>',4)),(o(),n(d,null,{default:t(()=>[r(i,{id:"mermaid-324",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20subgraph%20Decision%5B%22Architecture%20selection%22%5D%0A%20%20%20%20%20%20%20%20direction%20TB%0A%20%20%20%20%20%20%20%20Q1%7B%22Need%20sub-second%20latency%3Cbr%2F%3Efor%20user-facing%20decisions%3F%22%7D%0A%20%20%20%20%20%20%20%20Q1%20--%3E%7C%22No%22%7C%20A1%5B%22Batch%20%2F%20medallion%3Cbr%2F%3Elowest%20TCO%22%5D%0A%20%20%20%20%20%20%20%20Q1%20--%3E%7C%22Yes%22%7C%20Q2%7B%22Same%20team%20owns%3Cbr%2F%3Ebatch%20and%20streaming%3F%22%7D%0A%20%20%20%20%20%20%20%20Q2%20--%3E%7C%22No%22%7C%20A2%5B%22Lambda%3Cbr%2F%3Eclear%20ownership%20split%22%5D%0A%20%20%20%20%20%20%20%20Q2%20--%3E%7C%22Yes%22%7C%20Q3%7B%22Log%20retention%20%2B%3Cbr%2F%3Ereplay%20feasible%3F%22%7D%0A%20%20%20%20%20%20%20%20Q3%20--%3E%7C%22Yes%22%7C%20A3%5B%22Kappa%20%2F%20unified%3Cbr%2F%3Eone%20codebase%2C%20replay%20for%20reprocess%22%5D%0A%20%20%20%20%20%20%20%20Q3%20--%3E%7C%22No%22%7C%20A4%5B%22Lambda%3Cbr%2F%3Ebatch%20is%20the%20durable%20record%22%5D%0A%20%20%20%20end%0A"})]),fallback:t(()=>[...e[4]||(e[4]=[s(" Loading... ",-1)])]),_:1})),e[11]||(e[11]=a('<table tabindex="0"><thead><tr><th>Org profile</th><th>Recommended pattern</th><th>Why</th></tr></thead><tbody><tr><td>Small team, analytics-only</td><td>Batch + medallion on a lakehouse</td><td>simplest, cheapest, fewest moving parts</td></tr><tr><td>Mixed batch + streaming, one team</td><td>Unified engine (Spark/Flink) + medallion</td><td>one codebase, two modes, replay for reprocessing</td></tr><tr><td>High-scale, latency-critical product</td><td>Kappa + stream processor + serving layer</td><td>log is truth; replay is a first-class operation</td></tr><tr><td>Regulated, multi-team, strict SLAs</td><td>Lambda-style split with shared schema contracts</td><td>clear ownership, audit trail, independent scaling</td></tr></tbody></table><details class="details custom-block"><summary>Deep-dive: the replay cost nobody budgets for</summary><p>Kappa&#39;s &quot;just replay the log&quot; assumes the log is retained (often 30–90 days or indefinite in cloud object storage) and that replay is actually fast enough. A month of high-throughput events can take hours to replay through a stateful job, and during replay you are either serving stale data or running a parallel pipeline. Budget for it: measure replay throughput, test it quarterly, and have a snapshot/checkpoint strategy to shorten recovery.</p></details><details class="details custom-block"><summary>Deep-dive: why Lambda persists in the serving layer</summary><p>Even with a unified engine, the <em>serving</em> side often splits: an OLAP store (Pinot, Druid, ClickHouse) for user-facing queries and a lakehouse for deep history and ad-hoc. This is Lambda-shaped but the compute layer is unified — one pipeline writing to two sinks, not two pipelines computing the same thing twice.</p></details><h2 id="apache-beam-the-model-that-made-kappa-practical" tabindex="-1">Apache Beam: the model that made Kappa practical <a class="header-anchor" href="#apache-beam-the-model-that-made-kappa-practical" aria-label="Permalink to &quot;Apache Beam: the model that made Kappa practical&quot;">​</a></h2><p>Spark and Flink unified <em>engines</em>; Apache Beam unified the <em>programming model</em>. Beam (from Google&#39;s Dataflow model paper, Akidau et al.) poses four questions — <strong>what</strong> results you compute, <strong>where</strong> in event time, <strong>when</strong> in processing time results materialize (triggers), <strong>how</strong> later refinements relate — and makes the answer to &quot;batch or stream?&quot; a property of the <em>data</em>, not the code. A <code>PCollection</code> is a dataset that may be bounded or unbounded; a <code>PTransform</code> graph is a DAG that never changes between the two.</p>',5)),(o(),n(d,null,{default:t(()=>[r(i,{id:"mermaid-402",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20subgraph%20Pipe%5B%22One%20pipeline%20definition%22%5D%0A%20%20%20%20%20%20%20%20direction%20TB%0A%20%20%20%20%20%20%20%20SRC%5B%22Read%3Cbr%2F%3Efile%20or%20topic%22%5D%20--%3E%20T1%5B%22ParDo%3Cbr%2F%3Eper-element%20UDF%22%5D%0A%20%20%20%20%20%20%20%20T1%20--%3E%20W%5B%22Window%3Cbr%2F%3Eassign%20event-time%20windows%22%5D%0A%20%20%20%20%20%20%20%20W%20--%3E%20G%5B%22GroupByKey%20or%20Combine%3Cbr%2F%3Eshuffle%20boundary%22%5D%0A%20%20%20%20%20%20%20%20G%20--%3E%20T2%5B%22ParDo%3Cbr%2F%3Eemit%20results%22%5D%0A%20%20%20%20%20%20%20%20T2%20--%3E%20SNK%5B%22Write%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Src%5B%22Boundedness%20is%20a%20source%20property%22%5D%0A%20%20%20%20%20%20%20%20direction%20LR%0A%20%20%20%20%20%20%20%20B%5B%22Bounded%20PCollection%3Cbr%2F%3Efiles%2C%20table%20export%2C%20replayed%20log%22%5D%0A%20%20%20%20%20%20%20%20U%5B%22Unbounded%20PCollection%3Cbr%2F%3EKafka%2C%20PubSub%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Run%5B%22Same%20graph%2C%20swappable%20runner%22%5D%0A%20%20%20%20%20%20%20%20direction%20LR%0A%20%20%20%20%20%20%20%20R1%5B%22Direct%22%5D%0A%20%20%20%20%20%20%20%20R2%5B%22Dataflow%22%5D%0A%20%20%20%20%20%20%20%20R3%5B%22Flink%22%5D%0A%20%20%20%20%20%20%20%20R4%5B%22Spark%22%5D%0A%20%20%20%20end%0A%20%20%20%20B%20--%3E%20SRC%0A%20%20%20%20U%20--%3E%20SRC%0A%20%20%20%20SNK%20--%3E%20Run%0A"})]),fallback:t(()=>[...e[5]||(e[5]=[s(" Loading... ",-1)])]),_:1})),e[12]||(e[12]=a('<p>Reprocessing in Kappa terms is just swapping the source: point <code>Read</code> at retained history and the identical graph — windows, triggers, joins, side inputs — runs unchanged. That is Kappa&#39;s &quot;one codebase&quot; enforced by the type system, not by discipline.</p><h3 id="windowing-batch-s-global-window-vs-unified-semantics" tabindex="-1">Windowing: batch&#39;s global window vs unified semantics <a class="header-anchor" href="#windowing-batch-s-global-window-vs-unified-semantics" aria-label="Permalink to &quot;Windowing: batch&#39;s global window vs unified semantics&quot;">​</a></h3><p>In a batch world every record implicitly lives in one window that closes when the input ends. Beam makes that explicit: the default is <code>GlobalWindows</code>, and a bounded source simply advances the watermark to end-of-time so the default trigger fires once. The same code on an unbounded source keeps the window open and emits per trigger.</p><table tabindex="0"><thead><tr><th>Concern</th><th>Pure batch view</th><th>Beam unified view</th></tr></thead><tbody><tr><td>Default window</td><td>the whole dataset, implicit</td><td><code>GlobalWindows</code>, explicit and re-assignable via <code>Window.into</code></td></tr><tr><td>Event time</td><td>ignored — data is &quot;all here&quot;</td><td>every element carries a timestamp; watermark heuristics drive progress</td></tr><tr><td>Result emission</td><td>once, at job end</td><td>trigger-defined; on bounded data the watermark reaching end-of-window fires once</td></tr><tr><td>&quot;Late&quot; data</td><td>impossible by definition</td><td>real — handled by allowed lateness, refinements, or side outputs</td></tr><tr><td>History recompute</td><td>rerun the job</td><td>replay the source as a bounded <code>PCollection</code>, same graph</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">⚠️ Risk / production failure mode</p><p>A trigger is a <em>recommendation</em>, not a contract — a runner may legally skip or merge firings (batch runners routinely emit a single pane). Never write correctness logic that depends on pane count; use triggers for latency, <code>PAssert</code>-style tests for semantics.</p></div><h3 id="joining-patterns-side-inputs-vs-cogroupbykey" tabindex="-1">Joining patterns: side inputs vs CoGroupByKey <a class="header-anchor" href="#joining-patterns-side-inputs-vs-cogroupbykey" aria-label="Permalink to &quot;Joining patterns: side inputs vs CoGroupByKey&quot;">​</a></h3><p>Beam gives two canonical ways to bring a second stream into a <code>ParDo</code>, and the choice is an operational one, not a stylistic one.</p><table tabindex="0"><thead><tr><th>Pattern</th><th>Mechanism</th><th>Memory bound</th><th>Ordering semantics</th><th>Use when</th></tr></thead><tbody><tr><td>Side input (<code>View.asSingleton</code> / <code>asMap</code> / <code>asList</code> / <code>asMultimap</code>)</td><td>secondary <code>PCollection</code> reduced to a <code>PCollectionView</code>, read inside <code>DoFn</code></td><td>the <em>entire</em> view must fit per worker (except <code>asIterable</code>)</td><td>main input waits for the side-input window&#39;s first pane; later panes update asynchronously</td><td>small, slowly-changing reference data; runtime config</td></tr><tr><td><code>CoGroupByKey</code></td><td>each input tagged with <code>TupleTag</code>, <code>GroupByKey</code> over same key + window</td><td>per-key iterables only (some runners still require per-key fit)</td><td>joins strictly within compatible windows; result completeness waits for window end + allowed lateness</td><td>stream–stream joins too large for memory</td></tr><tr><td>Stateful <code>DoFn</code> + event-time timer</td><td>one stream buffered in per-key state, other drives <code>@OnTimer</code></td><td>per-key state, runner-managed and checkpointed</td><td>you define the match window explicitly</td><td>asymmetric joins, custom expiry of buffered side</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">💡 Senior insight</p><p>The book&#39;s rule of thumb for side inputs: the main input <em>blocks</em> until the side input&#39;s window produces data, then processes updates asynchronously. That makes slowly-changing side inputs (config refreshed every few minutes) efficient — but a fast-changing view serializes your main stream behind view updates. If the &quot;side&quot; data is really a stream of record updates, it is a join — use <code>CoGroupByKey</code>, don&#39;t pretend it&#39;s a lookup.</p></div><h3 id="runner-portability-and-delivery-guarantees" tabindex="-1">Runner portability and delivery guarantees <a class="header-anchor" href="#runner-portability-and-delivery-guarantees" aria-label="Permalink to &quot;Runner portability and delivery guarantees&quot;">​</a></h3><p>Runners differ in <em>how</em> they execute the same graph: <strong>classic</strong> runners consume a pipeline in the same language as the SDK; <strong>portable</strong> runners serialize the pipeline to a protobuf representation and delegate UDF execution to an SDK harness over the Fn API — any-SDK flexibility at some per-call overhead. Portability is not total: Beam&#39;s published <strong>capability matrix</strong> records which model features (state, timers, merging windows, splittable <code>DoFn</code>s) each runner fully supports. Check it before switching runners, not after.</p><table tabindex="0"><thead><tr><th>Runner</th><th>Batch</th><th>Streaming</th><th>Execution model</th><th>Notes</th></tr></thead><tbody><tr><td>Direct</td><td>✔</td><td>✔</td><td>in-JVM</td><td>testing only; exercises full semantics locally</td></tr><tr><td>Dataflow</td><td>✔</td><td>✔</td><td>remote managed state (Windmill-style)</td><td>reference implementation; state committed per bundle, workers effectively stateless → autoscaling-friendly</td></tr><tr><td>Flink</td><td>✔</td><td>✔</td><td>local state + periodic checkpoints</td><td>checkpoint interval <em>is</em> the commit cadence — too frequent adds overhead, too sparse delays source acks</td></tr><tr><td>Spark</td><td>✔</td><td>partial</td><td>micro-batch heritage</td><td>verify timer/state support in the capability matrix before relying on event-time triggers</td></tr></tbody></table><p>On guarantees: Beam&#39;s model requires that a <em>bundle</em> — the atomic unit of work — either fully commits or fully reverts. On failure every stateful transform resets to the last committed state and processing resumes, so duplicates can only escape through <strong>sinks that aren&#39;t idempotent</strong>. That yields the practical knob matrix:</p><table tabindex="0"><thead><tr><th>Knob</th><th>Runner</th><th>Effect</th></tr></thead><tbody><tr><td><code>--checkpointingInterval</code></td><td>Flink</td><td>state snapshot frequency = bundle-commit cadence; governs replay length on crash</td></tr><tr><td>bundle commit + remote state</td><td>Dataflow</td><td>consistent snapshot always available; at-least-once to non-idempotent sinks</td></tr><tr><td>idempotent sink writes</td><td>all</td><td>converts at-least-once delivery into effectively-once output — the only end-to-end lever that matters</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">💡 Senior insight</p><p>&quot;Exactly-once&quot; inside Beam means <em>each element affects state exactly once</em> — a bundle-atomicity property. The end-to-end story is still at-least-once delivery plus an idempotent sink. The book&#39;s failure example is the classic one: write to a non-transactional commit log, crash before checkpoint, replay → duplicate rows no downstream <code>DISTINCT</code> fully repairs because they carry different processing timestamps.</p></div><h2 id="🧠-quiz" tabindex="-1">🧠 Quiz <a class="header-anchor" href="#🧠-quiz" aria-label="Permalink to &quot;🧠 Quiz&quot;">​</a></h2>',16)),r(l,{questions:[{q:"What is the defining failure mode of the Lambda architecture?",options:["The serving layer cannot merge results","It cannot handle high throughput","The batch layer is too slow","The speed layer and batch layer implement the same logic and drift apart"],correct:3,explain:"Dual-codebase drift is the canonical Lambda pain: two teams, two engines, one business rule. Every schema change, edge case, and bugfix has to land identically in both, forever."},{q:"In the Kappa architecture, what is the source of truth?",options:["The append-only log","The speed layer","The serving layer","The batch layer"],correct:0,explain:"Kappa inverts the dependency: the immutable log (e.g., Kafka) is the source of truth, and all tables/views are derived. Reprocessing means replaying the log, not running a separate batch job."},{q:"What does a unified engine like Spark Structured Streaming or Flink give you that Lambda does not?",options:["Higher throughput","One codebase that can run in batch mode (bounded input) or streaming mode (unbounded input)","Built-in data quality checks","Cheaper compute"],correct:1,explain:"The unified engine treats batch as a bounded stream. One codebase handles both history reprocessing and live tailing — the practical end of the Lambda pattern."},{q:"In the medallion architecture, which layer should contain business-level aggregates ready for BI consumption?",options:["Silver","Bronze","Gold","A separate serving layer outside the medallion"],correct:2,explain:"Gold is the consumption layer: business metrics, star schemas, data marts. Bronze is raw, silver is cleaned/conformed, gold is modeled for use."},{q:"A Kappa pipeline has a bug that corrupted a month of output. What is the recovery path?",options:["There is no recovery — Kappa cannot reprocess","Run the batch layer","Fix the bug, redeploy, and replay the log from a known-good offset","Restore from database backup"],correct:2,explain:"Kappa reprocesses by replaying the log. You fix the code, reset consumer offsets (or trigger a bounded replay from a timestamp), and let the same stream job recompute correct output."},{q:"When would Lambda still be the right choice today?",options:["When serving requires genuinely different access patterns (e.g., sub-second OLAP store + deep-history warehouse) and the compute is unified","Never — it is obsolete","When you have unlimited budget","When the team does not know streaming"],correct:0,explain:"Modern Lambda splits at the serving tier, not the compute tier. One pipeline feeds both a fast OLAP store and a lakehouse; the architecture survives as a serving-layer pattern."}]}),r(l,{questions:[{q:"In Apache Beam, what determines whether a pipeline runs in batch or streaming mode?",options:["The boundedness of the source PCollection — the same graph runs both modes unchanged","A flag on each PTransform","The runner you choose","A separate batch pipeline class"],correct:0,explain:"Boundedness is a property of the data, not the code. Point the source at a bounded file or replayed log and the identical window/trigger/join graph executes as batch; point it at Kafka and it is a streaming job."},{q:"Two streams are too large for an in-memory lookup join in Beam. What is the right primitive?",options:["A bigger side input","CoGroupByKey — TupleTag both inputs and group by key within compatible windows","GroupByKey on one stream only","A global window over both"],correct:1,explain:"Side inputs must fit in worker memory per window; CoGroupByKey shuffles both inputs by (key, window) so only per-key iterables must materialize. It is the memory-safe stream-stream join."},{q:"Where does end-to-end effectively-once actually come from in a Beam pipeline?",options:["Bundle atomicity in the model plus an idempotent or transactional sink","Using the DirectRunner","Disabling retries","A runner flag called exactly-once"],correct:0,explain:"Runners guarantee a bundle commits fully or reverts — replay after a crash resends elements. Only an idempotent sink (upsert by key, partition overwrite, transactional write) turns that at-least-once delivery into effectively-once output."}]}),e[13]||(e[13]=a('<h2 id="further-reading" tabindex="-1">Further reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further reading&quot;">​</a></h2><ul><li><a href="http://nathanmarz.com/blog/how-to-beat-the-cap-theorem.html" target="_blank" rel="noreferrer">Nathan Marz, &quot;How to beat the CAP theorem&quot;</a> — the original Lambda argument</li><li><a href="https://www.linkedin.com/pulse/questioning-lambda-architecture-jay-kreps/" target="_blank" rel="noreferrer">Jay Kreps, &quot;Questioning the Lambda Architecture&quot;</a> — the Kappa counter-proposal</li><li><a href="https://milinda.pathirage.org/kappa-architecture.com/" target="_blank" rel="noreferrer">kappa-architecture.com</a> — Kreps&#39; canonical summary, hosted mirror</li><li><a href="https://www.manning.com/books/big-data" target="_blank" rel="noreferrer"><em>Big Data</em> (Marz &amp; Warren)</a> — the Lambda reference</li><li><strong>Building Big Data Pipelines with Apache Beam</strong> — Jan Lukavský (2022), <a href="https://www.packtpub.com/en-us/product/building-big-data-pipelines-with-apache-beam-9781800564937" target="_blank" rel="noreferrer">Packt</a> — the unified batch/streaming model, runners, state and portability deep-dive</li><li><a href="https://docs.databricks.com/en/lakehouse/medallion" target="_blank" rel="noreferrer">Databricks — What is the medallion lakehouse architecture?</a> — the de-facto industry layering pattern</li><li><a href="https://flink.apache.org/" target="_blank" rel="noreferrer">Apache Flink documentation</a> — batch mode and unified execution</li><li><a href="https://spark.apache.org/docs/latest/structured-streaming-programming-guide.html" target="_blank" rel="noreferrer">Spark Structured Streaming Programming Guide</a> — micro-batch and continuous triggers</li></ul>',2))])}const A=h(u,[["render",m]]);export{v as __pageData,A as default};
